-- Test-only additive version of the frozen legacy133 policy.
-- Used only in an isolated pre-348 compatibility fixture schema.
DO $scene_seed$
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended('native_scene_policy:'||'wakemu.mineral_tower_36.native_start.v1:isolated-v2',0));
    IF EXISTS (SELECT 1 FROM native_scene_policies WHERE policy_id='wakemu.mineral_tower_36.native_start.v1:isolated-v2') THEN
        IF NOT EXISTS (SELECT 1 FROM native_scene_policies WHERE policy_id='wakemu.mineral_tower_36.native_start.v1:isolated-v2' AND policy_sha256='9ce844c4453135b463025678e9ffd02cbbfa0c7adad011f0860a82106d4e56dc' AND published) THEN
            RAISE EXCEPTION 'Existing native scene identity differs from reviewed immutable seed';
        END IF;
        RETURN;
    END IF;
    UPDATE native_scene_policies SET published=true WHERE policy_id='wakemu.mineral_tower_36.native_start.v1:isolated-v2';
END $scene_seed$;
